import pytest


def rotl8(x: int, k: int) -> int:
    """Rotate the 8-bit value x left by k bits, wrapping high bits around.

    x must be in range 0..255 and k in range 0..7. The result is also
    in range 0..255.
    """
    return ((x << k) | (x >> (8 - k))) & 0xFF


def _reference(x: int, k: int) -> int:
    bits = format(x, "08b")
    return int(bits[k:] + bits[:k], 2)


def test_rotl8_zero_shift_is_identity() -> None:
    for x in (0, 1, 0x80, 0xA5, 255):
        assert rotl8(x, 0) == x


def test_rotl8_simple_shift_no_wrap() -> None:
    assert rotl8(0b00000001, 1) == 0b00000010
    assert rotl8(0b00000011, 2) == 0b00001100


def test_rotl8_wraps_high_bits() -> None:
    assert rotl8(0b10000000, 1) == 0b00000001
    assert rotl8(0b10000001, 1) == 0b00000011
    assert rotl8(0b11000000, 2) == 0b00000011
    assert rotl8(0b10110001, 4) == 0b00011011


def test_rotl8_max_shift() -> None:
    assert rotl8(0b00000001, 7) == 0b10000000
    assert rotl8(0b00000010, 7) == 0b00000001


def test_rotl8_all_zeros_and_all_ones() -> None:
    for k in range(8):
        assert rotl8(0, k) == 0
        assert rotl8(255, k) == 255


def test_rotl8_result_in_range() -> None:
    for x in range(256):
        for k in range(8):
            assert 0 <= rotl8(x, k) <= 255


def test_rotl8_matches_reference_exhaustively() -> None:
    for x in range(256):
        for k in range(8):
            assert rotl8(x, k) == _reference(x, k)


def test_rotl8_composition() -> None:
    for x in range(256):
        for a in range(8):
            for b in range(8):
                assert rotl8(rotl8(x, a), b) == rotl8(x, (a + b) % 8)


def test_rotl8_inverse_by_complement_shift() -> None:
    for x in range(256):
        for k in range(1, 8):
            assert rotl8(rotl8(x, k), 8 - k) == x if 8 - k <= 7 else True


def test_rotl8_preserves_popcount() -> None:
    for x in range(256):
        for k in range(8):
            assert rotl8(x, k).bit_count() == x.bit_count()


@pytest.mark.parametrize(
    ("x", "k", "expected"),
    [
        (0x01, 4, 0x10),
        (0xF0, 4, 0x0F),
        (0x81, 3, 0x0C),
        (0xAA, 1, 0x55),
        (0x55, 1, 0xAA),
    ],
)
def test_rotl8_known_values(x: int, k: int, expected: int) -> None:
    assert rotl8(x, k) == expected
